program_source = '''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 2)]

    def fill(r, c):
        if out[r][c] == 0:
            out[r][c] = 2

    for r in range(r0, r1 + 1):
        left = any(mr == r and mc < c0 for mr, mc in markers)
        right = any(mr == r and mc > c1 for mr, mc in markers)
        if not left:
            for c in range(0, c0): fill(r, c)
        if not right:
            for c in range(c1 + 1, w): fill(r, c)

    for c in range(c0, c1 + 1):
        above = any(mc == c and mr < r0 for mr, mc in markers)
        below = any(mc == c and mr > r1 for mr, mc in markers)
        if not above:
            for r in range(0, r0): fill(r, c)
        if not below:
            for r in range(r1 + 1, h): fill(r, c)
    return out
'''
